#!/usr/bin/env node
// Build the DSH bundle under dsh/ from the canonical Skill sources.
//
//   node scripts/build-dsh-bundle.js [--check] [--commit <40-hex>] [--timestamp <unix>]
//
// A DSH bundle is a package whose package.json declares dsh.bundle.patch; the
// patch inserts a Host plugin that registers the wishmachine skill provider.
// This script keeps the bundle self-contained (pnpm installs only dsh/ plus its
// files): it copies SKILL.md, scripts/ and references/ into
// dsh/skills/wishmachine/, regenerates dsh/skill-meta.js, syncs versions and
// rebuilds the plugin-market index that offers the Git source.
//
// --check compares the generated tree with what is on disk and exits 1 on drift;
// CI runs it, so a release cannot forget to resync the bundle.
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { validateSkillManifest } from './skill-manifest.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const DEV_ONLY = new Set([
  'pack.js',
  'release.js',
  'check-imports.js',
  'check-structure.js',
  'skill-manifest.js',
  'build-dsh-bundle.js',
]);
const GIT_URL = 'https://github.com/Malxi/wishmachine.git';
const REPO_URL = 'https://github.com/Malxi/wishmachine';
const HOMEPAGE = 'https://github.com/Malxi/wishmachine';
const COMMIT_PATTERN = /^[0-9a-f]{40}$/;

function readJson(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function json(value) {
  return `${JSON.stringify(value, null, 2)}\n`;
}

// The bundle is a committed, platform-neutral artifact: normalize every copied
// text file to LF so a Windows working tree cannot make --check flag drift.
function toLf(text) {
  return text.replace(/\r\n/g, '\n');
}

function readText(file) {
  return toLf(fs.readFileSync(file, 'utf8'));
}

function walk(dir, base = dir, out = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true }).sort((left, right) => left.name.localeCompare(right.name))) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, base, out);
    else out.push(path.relative(base, full).split(path.sep).join('/'));
  }
  return out;
}

function copySourceTree(files, sourceDir, targetDir, filter = () => true) {
  for (const relative of walk(sourceDir)) {
    if (!filter(relative)) continue;
    files.set(`${targetDir}/${relative}`, readText(path.join(sourceDir, relative)));
  }
}

function gitHead(root) {
  const run = spawnSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' });
  if (run.status !== 0) return '';
  return String(run.stdout || '').trim();
}

function marketIndex(existing, context) {
  const plugin = {
    name: 'wishmachine-dsh',
    title: { en: 'Wishmachine', zh: '小说许愿机' },
    description: {
      en: 'DSH bundle that adds the wishmachine skill: a deterministic novel-project CLI for setup, outline, chapter writes and checks.',
      zh: '添加 wishmachine 技能的 DSH bundle：确定性小说项目管理、大纲/正文写入与检查 CLI。',
    },
    icon: 'icon.svg',
    author: 'Malxi',
    homepage: HOMEPAGE,
    repository: { url: REPO_URL, directory: 'dsh' },
    versions: [{
      version: context.version,
      publishTimestamp: context.timestamp,
      source: { type: 'git', url: GIT_URL, commit: context.commit, path: 'dsh' },
      engines: { dsh: context.enginesDsh },
    }],
  };
  const base = existing && existing.format === 1 && Array.isArray(existing.plugins)
    ? existing
    : {
      format: 1,
      title: { en: 'Wishmachine', zh: '小说许愿机' },
      description: {
        en: 'Official Wishmachine DSH bundle index.',
        zh: '小说许愿机 DSH bundle 的官方索引。',
      },
    };
  return {
    ...base,
    title: base.title || { en: 'Wishmachine', zh: '小说许愿机' },
    description: base.description || {
      en: 'Official Wishmachine DSH bundle index.',
      zh: '小说许愿机 DSH bundle 的官方索引。',
    },
    plugins: [plugin],
  };
}

export function planBundle(options = {}) {
  const root = path.resolve(options.root || ROOT);
  const dshDir = path.join(root, 'dsh');
  const packageDoc = readJson(path.join(root, 'package.json'));
  const version = String(packageDoc.version || '');
  const skillText = readText(path.join(root, 'SKILL.md'));
  const manifest = validateSkillManifest(skillText, { expectedVersion: version });
  if (!manifest.ok) throw new Error(`SKILL.md manifest is invalid: ${manifest.errors.join('; ')}`);
  const dshPackage = readJson(path.join(dshDir, 'package.json'));
  const enginesDsh = dshPackage.engines?.dsh || '';
  if (!enginesDsh) throw new Error('dsh/package.json needs engines.dsh');
  const scriptsPackage = readJson(path.join(root, 'scripts', 'package.json'));
  const files = new Map();

  files.set('dsh/skill-meta.js', `// Generated by scripts/build-dsh-bundle.js from SKILL.md frontmatter.\nexport const description = ${JSON.stringify(manifest.data.description)};\n`);
  files.set('dsh/skills/wishmachine/SKILL.md', skillText);
  copySourceTree(files, path.join(root, 'references'), 'dsh/skills/wishmachine/references');
  copySourceTree(files, path.join(root, 'scripts'), 'dsh/skills/wishmachine/scripts', (relative) => {
    if (relative === 'package.json') return false;
    return !DEV_ONLY.has(relative);
  });
  files.set('dsh/skills/wishmachine/scripts/package.json', json({ ...scriptsPackage, version }));
  files.set('dsh/package.json', json({ ...dshPackage, version }));

  const commit = String(options.commit || gitHead(root) || existingCommit(root) || '');
  if (!COMMIT_PATTERN.test(commit)) {
    throw new Error('a 40-hex commit is required: pass --commit <sha> or commit the bundle sources first');
  }
  const existingIndex = fs.existsSync(path.join(dshDir, 'market', 'index.json'))
    ? readJson(path.join(dshDir, 'market', 'index.json'))
    : null;
  const previous = existingIndex?.plugins?.[0]?.versions?.[0];
  const timestamp = Number(options.timestamp)
    || (previous && previous.version === version ? previous.publishTimestamp : Math.floor(Date.now() / 1000));
  const index = marketIndex(existingIndex, { version, commit, timestamp, enginesDsh });
  files.set('dsh/market/index.json', json(index));
  files.set('dsh/market/icon.svg', readText(path.join(dshDir, 'icon.svg')));
  return { root, version, commit, files };
}

function existingCommit(root) {
  const file = path.join(root, 'dsh', 'market', 'index.json');
  if (!fs.existsSync(file)) return '';
  try {
    return readJson(file)?.plugins?.[0]?.versions?.[0]?.source?.commit || '';
  } catch {
    return '';
  }
}

function comparePlan(plan) {
  const problems = [];
  for (const [relative, content] of plan.files) {
    const file = path.join(plan.root, relative);
    if (!fs.existsSync(file)) {
      problems.push(`missing ${relative}`);
      continue;
    }
    if (readText(file) !== content) problems.push(`stale ${relative}`);
  }
  const generatedSkillDir = path.join(plan.root, 'dsh', 'skills', 'wishmachine');
  if (fs.existsSync(generatedSkillDir)) {
    for (const relative of walk(generatedSkillDir)) {
      if (!plan.files.has(`dsh/skills/wishmachine/${relative}`)) problems.push(`unexpected dsh/skills/wishmachine/${relative}`);
    }
  }
  return problems;
}

function writePlan(plan) {
  const skillRoot = path.join(plan.root, 'dsh', 'skills', 'wishmachine');
  fs.rmSync(skillRoot, { recursive: true, force: true });
  const written = [];
  for (const [relative, content] of plan.files) {
    const file = path.join(plan.root, relative);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content, 'utf8');
    written.push(relative);
  }
  return written;
}

function parseArgs(argv) {
  const options = { check: false, commit: '', timestamp: 0, root: ROOT, help: false };
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === '--check') options.check = true;
    else if (arg === '--help' || arg === '-h') options.help = true;
    else if (arg === '--commit' || arg === '--timestamp') {
      const value = argv[index + 1];
      if (!value) throw new Error(`${arg} requires a value`);
      if (arg === '--commit') options.commit = value;
      else options.timestamp = Number(value);
      index += 1;
    } else if (arg.startsWith('--commit=')) options.commit = arg.slice('--commit='.length);
    else if (arg.startsWith('--timestamp=')) options.timestamp = Number(arg.slice('--timestamp='.length));
    else throw new Error(`unknown option: ${arg}`);
  }
  return options;
}

function usage() {
  return [
    'Usage: node scripts/build-dsh-bundle.js [--check] [--commit <40-hex>] [--timestamp <unix>]',
    '  --check             compare the generated dsh/ tree with the sources (CI)',
    '  --commit <sha>      commit the market index pins (defaults to HEAD)',
    '  --timestamp <unix>  publish timestamp for the index version',
  ].join('\n');
}

// --check must ignore HEAD drift: the market index is updated by hand after a release commit.
function readPinnedIndex(root) {
  const file = path.join(root, 'dsh', 'market', 'index.json');
  if (!fs.existsSync(file)) return {};
  try {
    const version = readJson(file)?.plugins?.[0]?.versions?.[0] || {};
    return { commit: version.source?.commit || '', timestamp: version.publishTimestamp || 0 };
  } catch {
    return {};
  }
}

function main(argv = process.argv.slice(2)) {
  try {
    const options = parseArgs(argv);
    if (options.help) {
      process.stdout.write(`${usage()}\n`);
      return;
    }
    const pinned = options.check ? readPinnedIndex(ROOT) : {};
    const plan = planBundle({ commit: options.commit || pinned.commit, timestamp: options.timestamp || pinned.timestamp });
    const summary = {
      ok: true,
      action: 'dsh-bundle',
      version: plan.version,
      commit: plan.commit,
      files: plan.files.size,
      check: options.check,
    };
    if (options.check) {
      const problems = comparePlan(plan);
      summary.ok = problems.length === 0;
      summary.problems = problems;
      if (!summary.ok) process.exitCode = 1;
    } else {
      summary.written = writePlan(plan);
    }
    process.stdout.write(`${JSON.stringify(summary, null, 2)}\n`);
  } catch (error) {
    process.stdout.write(`${JSON.stringify({ ok: false, error: { code: 'dsh-bundle.failed', message: error.message } })}\n`);
    process.stderr.write(`dsh bundle failed: ${error.message}\n`);
    process.exitCode = 1;
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
